-- Knowledge base pages: everything authored is one kind, a page of Markdown, nested in one tree for
-- the whole workspace. Publishing is the only write of a page's content, and each publish is a
-- version. See docs/knowledge.md, Pages.

CREATE TABLE pages (
    -- Generated by the API (UUIDv7).
    id UUID PRIMARY KEY,
    -- The page it sits under; NULL at the top of the tree. There are no spaces: one tree, to any
    -- depth. A live page's parent is always live, and a page is never under itself at any depth;
    -- the API holds both, under one lock for every change to the tree.
    parent_id UUID REFERENCES pages (id),
    -- Its place among its siblings, lowest first. Gapped, so a page lands between two others by
    -- writing its own row alone; siblings are renumbered only when two have no room between them
    -- (crate::models::page, POSITION_GAP). Deleted pages keep theirs, so a restored page comes back
    -- where it was.
    position BIGINT NOT NULL,
    -- What the page says now: a copy of its newest version, kept here so the tree and title
    -- searches read one table. On one line: the API trims it and collapses its whitespace.
    title TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 300),
    -- Markdown, which may be empty: a page can exist only to hold others. 100,000 characters is
    -- what the knowledge index takes from one source (docs/knowledge.md, Timeline records, Size).
    body TEXT NOT NULL DEFAULT '' CHECK (char_length(body) <= 100000),
    -- A learning's category and evidence (docs/knowledge.md, Learnings), set together on a page
    -- that is a learning. Its evidence is part of what is indexed.
    category TEXT REFERENCES learning_categories (key),
    evidence TEXT CHECK (char_length(evidence) BETWEEN 1 AND 20000),
    -- The newest of its versions.
    current_version INTEGER NOT NULL DEFAULT 1 CHECK (current_version >= 1),
    -- Agents may not write this page, only propose to it; people edit it directly. The company doc's
    -- pages are the reason: an agent's change waits for a person to approve it.
    proposal_only BOOLEAN NOT NULL DEFAULT FALSE,
    -- Soft delete: NULL while the page is live. A deleted page leaves the index and keeps its
    -- versions. Its descendants take the same instant, which is how restoring it knows which of them
    -- went with it.
    deleted_at TIMESTAMPTZ,
    -- Who created it. Who changed it since is in its versions and its history.
    created_by UUID NOT NULL REFERENCES users (id),
    created_at TIMESTAMPTZ NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),

    CONSTRAINT pages_not_its_own_parent CHECK (parent_id <> id),
    CONSTRAINT pages_learning_fields_together CHECK ((category IS NULL) = (evidence IS NULL)),
    -- Siblings never tie, deleted ones included. Deferrable so renumbering a parent's children in
    -- one statement is checked when it ends rather than row by row. NULLS NOT DISTINCT, since the
    -- top of the tree is NULL. Its index reads a parent's children in order.
    CONSTRAINT pages_sibling_positions UNIQUE NULLS NOT DISTINCT (parent_id, position)
        DEFERRABLE INITIALLY IMMEDIATE
);

SELECT diesel_manage_updated_at('pages');

-- Counts and moves a category's learnings.
CREATE INDEX pages_category ON pages (category) WHERE category IS NOT NULL;

-- Every published version, never changed once written. The newest is what the page says now.
CREATE TABLE page_versions (
    page_id UUID NOT NULL REFERENCES pages (id) ON DELETE CASCADE,
    -- 1 when the page was created, then one more for each publish and each restore. What a publish
    -- names as the version it was edited from. The key, so two publishes cannot both take a number.
    version INTEGER NOT NULL CHECK (version >= 1),
    title TEXT NOT NULL CHECK (char_length(title) BETWEEN 1 AND 300),
    body TEXT NOT NULL CHECK (char_length(body) <= 100000),
    -- Text rather than a reference: a version records what it held, and outlives a category removed
    -- since.
    category TEXT CHECK (char_length(category) BETWEEN 1 AND 50),
    evidence TEXT CHECK (char_length(evidence) BETWEEN 1 AND 20000),
    -- The version a restore copied.
    restored_from INTEGER CHECK (restored_from >= 1),
    -- Who published it: a person, or the machine user of an agent of Elysium's own.
    created_by UUID NOT NULL REFERENCES users (id),
    -- The agent acting for them: an MCP client as `mcp:<client id>`, a coding or Studio session's
    -- agent as `session:<number>`, or a Project Manager as `project_manager:<project id>`. NULL when
    -- a person published it themselves, and for Elysia.
    agent TEXT CHECK (
        agent ~ '^(mcp:[^[:space:]]{1,255}|session:[0-9]{1,18}|project_manager:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$'
    ),
    -- What an MCP client called itself. A label only; `agent` is the identity.
    agent_name TEXT CHECK (char_length(agent_name) BETWEEN 1 AND 200),
    created_at TIMESTAMPTZ NOT NULL,

    PRIMARY KEY (page_id, version),
    CONSTRAINT page_versions_restored_an_earlier_version CHECK (restored_from < version),
    CONSTRAINT page_versions_agent_named_with_its_agent CHECK (
        agent IS NOT NULL OR agent_name IS NULL
    )
);

-- A page's history, one entry per change, shaped like learning_events: versions hold what a page
-- said, and this holds everything that happened to it, publishes included, so one table reads as a
-- page's history and as a feed across every page.
CREATE TABLE page_events (
    -- UUIDv7, so entries order as they were written.
    id UUID PRIMARY KEY,
    page_id UUID NOT NULL REFERENCES pages (id) ON DELETE CASCADE,
    -- `created`, `published`, `moved`, `deleted`, or `restored`. Text rather than an enum, as for
    -- learning_events, so a later kind needs no enum migration.
    kind TEXT NOT NULL CHECK (kind ~ '^[a-z][a-z_]{0,63}$'),
    -- Who made the change, and the agent acting for them, as on page_versions.
    created_by UUID NOT NULL REFERENCES users (id),
    agent TEXT CHECK (
        agent ~ '^(mcp:[^[:space:]]{1,255}|session:[0-9]{1,18}|project_manager:[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12})$'
    ),
    agent_name TEXT CHECK (char_length(agent_name) BETWEEN 1 AND 200),
    data JSONB NOT NULL CHECK (jsonb_typeof(data) = 'object'),
    created_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT page_events_agent_named_with_its_agent CHECK (
        agent IS NOT NULL OR agent_name IS NULL
    )
);

CREATE INDEX page_events_page_id_idx ON page_events (page_id, id);

-- A page is a source of the knowledge index: a column of its own, unique and cascading, as every
-- source is (docs/knowledge.md, Search).
ALTER TABLE knowledge_documents
    ADD COLUMN page_id UUID UNIQUE REFERENCES pages (id) ON DELETE CASCADE;

ALTER TABLE knowledge_documents DROP CONSTRAINT knowledge_documents_one_source;
ALTER TABLE knowledge_documents ADD CONSTRAINT knowledge_documents_one_source
    CHECK (num_nonnulls(timeline_record_id, learning_id, company_doc_section, page_id) = 1);
